package com.mobile.nodeide;

import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.text.*;
import android.view.*;
import android.widget.*;
import androidx.annotation.*;
import androidx.appcompat.app.AlertDialog;
import androidx.documentfile.provider.DocumentFile;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.*;
import org.eclipse.jgit.api.Git;
import java.io.*;
import java.util.*;

public class ProjectsFragment extends Fragment {
    private static final int IMPORT_TREE=31, IMPORT_FILE=32;
    MainActivity a; Rows rows; final List<File> files=new ArrayList<>(); String filter="";
    @Nullable public View onCreateView(@NonNull LayoutInflater i,ViewGroup c,Bundle b){
        View v=i.inflate(R.layout.fragment_list,c,false); a=(MainActivity)requireActivity(); ((TextView)v.findViewById(R.id.title)).setText("NodeSphere   ✦");
        EditText search=v.findViewById(R.id.search);search.setHint("Pesquisar projetos recentes"); search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){} public void onTextChanged(CharSequence s,int st,int before,int count){filter=s.toString();refresh();} public void afterTextChanged(Editable e){}});
        RecyclerView list=v.findViewById(R.id.list);list.setLayoutManager(new LinearLayoutManager(a));rows=new Rows(n->a.open(files.get(n)));list.setAdapter(rows);
        Button action=v.findViewById(R.id.action);action.setText("＋  Projeto / importar / clonar");action.setOnClickListener(w->actions());refresh();return v;
    }
    void refresh(){if(rows==null)return;files.clear();File[] all=a.projects().listFiles();if(all!=null) {Arrays.sort(all);for(File f:all)if(f.isDirectory()&&f.getName().toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))files.add(f);}List<String> labels=new ArrayList<>();for(File f:files)labels.add("⬡   "+f.getName()+"\n      ~/projects/"+f.getName());rows.set(labels);}
    void actions(){new AlertDialog.Builder(a).setTitle("Projetos").setItems(new String[]{"Novo projeto", "Importar pasta", "Importar arquivo", "Clonar repositório HTTPS"},(d,n)->{switch(n){case 0: create();break;case 1: startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),IMPORT_TREE);break;case 2: Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,IMPORT_FILE);break;case 3: cloneRepo();break;}}).show();}
    void create(){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(24,0,24,0);EditText input=new EditText(a);input.setHint("nome-do-projeto");Spinner type=new Spinner(a);String[] templates={"Servidor HTTP", "API Express", "Express fullstack"};type.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,templates));box.addView(input);box.addView(type);new AlertDialog.Builder(a).setTitle("Novo projeto Node.js").setView(box).setPositiveButton("Criar",(d,w)->{String name=input.getText().toString().trim();if(!validName(name)){a.message("Nome inválido: use letras, números, ponto, hífen ou sublinhado");return;}File dir=new File(a.projects(),name);if(dir.exists()){a.message("Projeto já existe");return;}try{if(!dir.mkdir())throw new IOException("Não foi possível criar projeto");int t=type.getSelectedItemPosition();String deps=t==0?"":" ,\n  \"dependencies\": { \"express\": \"^4.21.2\" }";MainActivity.write(new File(dir,"package.json"),"{\n  \"name\": \""+name.toLowerCase(Locale.ROOT)+"\",\n  \"version\": \"1.0.0\",\n  \"scripts\": { \"start\": \"node server.js\" }"+deps+"\n}\n");String server=t==0?"const http = require('http');\nhttp.createServer((req, res) => {\n  res.writeHead(200, { 'Content-Type': 'text/plain' });\n  res.end('Hello from NodeSphere!');\n}).listen(3000);\n":"const express = require('express');\nconst app = express();\napp.use(express.json());\n"+(t==2?"app.use(express.static('public'));\n":"app.get('/', (req, res) => res.json({ ok: true }));\n")+"app.listen(3000, () => console.log('Listening on port 3000'));\n";MainActivity.write(new File(dir,"server.js"),server);if(t==2)MainActivity.write(new File(dir,"public/index.html"),"<!doctype html>\n<html><head><meta charset=\"utf-8\"><title>NodeSphere</title></head><body><h1>Olá, Node.js!</h1></body></html>\n");a.open(dir);}catch(IOException e){a.message(e.getMessage());}}).setNegativeButton("Cancelar",null).show();}
    boolean validName(String s){return s.matches("[a-zA-Z0-9][a-zA-Z0-9._-]{0,63}");}
    @Override public void onActivityResult(int request,int result,@Nullable Intent data){super.onActivityResult(request,result,data);if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();DocumentFile doc=request==IMPORT_TREE?DocumentFile.fromTreeUri(a,uri):DocumentFile.fromSingleUri(a,uri);if(doc==null){a.message("Não foi possível abrir o documento");return;}EditText name=new EditText(a);String suggested=request==IMPORT_TREE?doc.getName():"arquivo-importado";name.setText(suggested==null?"importado":suggested.replaceAll("[^a-zA-Z0-9._-]","-"));new AlertDialog.Builder(a).setTitle("Nome da cópia local").setMessage("Os arquivos serão copiados para o armazenamento privado; edições não alteram o original.").setView(name).setPositiveButton("Importar",(d,w)->{String value=name.getText().toString().trim();if(!validName(value)||new File(a.projects(),value).exists()){a.message("Nome inválido ou já existente");return;}File dest=new File(a.projects(),value);if(!dest.mkdir()){a.message("Não foi possível criar pasta");return;}a.message("Importação iniciada");new Thread(()->{try{if(request==IMPORT_TREE)copyTree(doc,dest,0);else copyFile(doc,new File(dest,safeName(doc.getName())));a.runOnUiThread(()->{if(isAdded())a.open(dest);});}catch(Exception e){deleteTree(dest);a.runOnUiThread(()->{if(isAdded())a.message("Erro ao importar: "+e.getMessage());});}}).start();}).setNegativeButton("Cancelar",null).show();}
    String safeName(String name)throws IOException{if(name==null||name.isEmpty()||name.equals(".")||name.equals("..")||name.contains("/")||name.contains("\\"))throw new IOException("Nome de documento inválido");return name;}
    void copyTree(DocumentFile source,File dest,int depth)throws IOException{if(depth>32)throw new IOException("Árvore muito profunda");for(DocumentFile child:source.listFiles()){File target=new File(dest,safeName(child.getName()));if(target.exists())throw new IOException("Nome duplicado: "+target.getName());if(child.isDirectory()){if(!target.mkdir())throw new IOException("Falha ao criar diretório");copyTree(child,target,depth+1);}else if(child.isFile())copyFile(child,target);}}
    void copyFile(DocumentFile doc,File dest)throws IOException{try(InputStream in=a.getContentResolver().openInputStream(doc.getUri());OutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException("Documento indisponível");byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}
    void cloneRepo(){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(24,0,24,0);EditText url=new EditText(a),name=new EditText(a);url.setHint("https://github.com/organização/repositório.git");name.setHint("nome local do projeto");box.addView(url);box.addView(name);new AlertDialog.Builder(a).setTitle("Clonar repositório público").setView(box).setPositiveButton("Clonar",(d,w)->{String u=url.getText().toString().trim(),n=name.getText().toString().trim();File dest=new File(a.projects(),n);if(!u.startsWith("https://")||!validName(n)||dest.exists()){a.message("URL HTTPS ou nome inválido, ou projeto existente");return;}if(!dest.mkdir()){a.message("Não foi possível criar pasta");return;}a.message("Clonagem iniciada; aguarde");new Thread(()->{try{try(Git ignored=Git.cloneRepository().setURI(u).setDirectory(dest).call()){}a.runOnUiThread(()->{if(isAdded())a.open(dest);});}catch(Exception e){deleteTree(dest);a.runOnUiThread(()->{if(isAdded())a.message("Erro ao clonar: "+e.getMessage());});}}).start();}).setNegativeButton("Cancelar",null).show();}
    void deleteTree(File f){if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File c:children)deleteTree(c);}f.delete();}
}
